//! Holtmail's HTTP API: sign-in, archives, folders, message lists, search, the reader and
//! downloads.
//!
//! Every response is JSON except bodies, raw messages and attachments. Every route except the
//! sign-in routes and the OpenAPI description needs a session cookie. The OpenAPI description is
//! served at `/api/openapi.json` and generated by [`openapi_json`].

mod dto;
mod routes;
mod session;

use std::sync::Arc;

use axum::Router;
use axum::http::StatusCode;
use axum::middleware::{from_fn, from_fn_with_state};
use axum::response::{IntoResponse, Response};
use axum::routing::{any, get, post};
use holtmail_auth::Auth;
use holtmail_blob::BlobStore;
use holtmail_index::SearchIndex;
use holtmail_store::Store;
use utoipa::OpenApi;
use utoipa::openapi::security::{ApiKey, ApiKeyValue, SecurityScheme};

use dto::*;
pub use session::{CurrentUser, SESSION_COOKIE};

/// What the API reads from.
#[derive(Clone)]
pub struct ApiState {
    /// Message bytes.
    pub blobs: Arc<dyn BlobStore>,
    /// Metadata.
    pub store: Arc<dyn Store>,
    /// Search.
    pub index: Arc<dyn SearchIndex>,
    /// Sign-in.
    pub auth: Arc<Auth>,
    /// Mark the session cookie `Secure` on every response, for instances served over https.
    /// Without it the cookie is `Secure` only when `X-Forwarded-Proto` is `https`.
    pub secure_cookies: bool,
}

/// The API routes under `/api`.
///
/// State-changing requests must be `application/json` and, when they carry an `Origin`, come
/// from the same host; others are refused with `415` and `403`. Routes other than
/// `/api/session`, `/api/setup`, `/api/login`, `/api/logout` and `/api/openapi.json` answer `401`
/// without a live session; unknown paths under `/api/` answer `404` to signed-in users.
pub fn router(state: ApiState) -> Router {
    let state = Arc::new(state);
    let protected = Router::new()
        .route("/api/archives", get(routes::list_archives))
        .route("/api/archives/{id}", get(routes::get_archive))
        .route("/api/archives/{id}/accounts", get(routes::list_accounts))
        .route("/api/archives/{id}/folders", get(routes::list_folders))
        .route("/api/archives/{id}/messages", get(routes::list_messages))
        .route("/api/archives/{id}/search", get(routes::search))
        .route("/api/messages/{id}", get(routes::get_message))
        .route("/api/messages/{id}/body", get(routes::get_body))
        .route("/api/messages/{id}/raw", get(routes::get_raw))
        .route(
            "/api/messages/{id}/attachments/{ordinal}",
            get(routes::get_attachment),
        )
        .route("/api/threads/{id}", get(routes::get_thread))
        .route("/api/{*rest}", any(routes::unknown))
        .route_layer(from_fn_with_state(state.clone(), session::require_session));
    Router::new()
        .route("/api/session", get(session::current))
        .route(
            "/api/setup",
            get(session::setup_status).post(session::setup),
        )
        .route("/api/login", post(session::login))
        .route("/api/logout", post(session::logout))
        .route("/api/openapi.json", get(routes::openapi))
        .merge(protected)
        .layer(from_fn(session::guard_writes))
        .with_state(state)
}

/// The OpenAPI description of [`router`] as pretty JSON.
pub fn openapi_json() -> String {
    ApiDoc::openapi()
        .to_pretty_json()
        .expect("the OpenAPI description serializes")
}

#[derive(OpenApi)]
#[openapi(
    info(title = "Holtmail", description = "Self-hosted email archive"),
    modifiers(&SessionCookie),
    security(("session" = [])),
    paths(
        session::current,
        session::setup_status,
        session::setup,
        session::login,
        session::logout,
        routes::list_archives,
        routes::get_archive,
        routes::list_accounts,
        routes::list_folders,
        routes::list_messages,
        routes::search,
        routes::get_message,
        routes::get_body,
        routes::get_raw,
        routes::get_attachment,
        routes::get_thread,
    ),
    components(schemas(
        ArchiveDto,
        StatsDto,
        AccountDto,
        FolderDto,
        AddressDto,
        MessageSummary,
        MessagePage,
        SearchResponse,
        AttachmentDto,
        LocationDto,
        MessageDetail,
        ThreadDto,
        ErrorDto,
        UserDto,
        SessionDto,
        SetupStatusDto,
        SetupRequest,
        LoginRequest,
    ))
)]
struct ApiDoc;

struct SessionCookie;

impl utoipa::Modify for SessionCookie {
    fn modify(&self, openapi: &mut utoipa::openapi::OpenApi) {
        openapi
            .components
            .get_or_insert_default()
            .add_security_scheme(
                "session",
                SecurityScheme::ApiKey(ApiKey::Cookie(ApiKeyValue::new(SESSION_COOKIE))),
            );
    }
}

struct ApiError(StatusCode, String);

impl ApiError {
    fn not_found(what: &str) -> Self {
        Self(StatusCode::NOT_FOUND, format!("{what} not found"))
    }

    fn bad_request(message: impl Into<String>) -> Self {
        Self(StatusCode::BAD_REQUEST, message.into())
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        (self.0, axum::Json(ErrorDto { error: self.1 })).into_response()
    }
}

impl<E: std::error::Error> From<E> for ApiError {
    fn from(error: E) -> Self {
        Self(StatusCode::INTERNAL_SERVER_ERROR, error.to_string())
    }
}

type ApiResult<T> = Result<T, ApiError>;

